// Worker entry for Cloudflare. It serves the Next.js app built by OpenNext and adds
// the daily ingest that `vercel.json` used to schedule (see `triggers.crons` in wrangler.jsonc).
// @ts-expect-error `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as handler } from "../.open-next/worker.js";

type Env = { CRON_SECRET?: string };
type Ctx = { waitUntil(promise: Promise<unknown>): void; passThroughOnException(): void };

const worker = {
  fetch: handler.fetch,

  async scheduled(controller: { cron: string; scheduledTime: number }, env: Env, ctx: Ctx) {
    if (!env.CRON_SECRET) throw new Error("CRON_SECRET is not set; skipping ingest");
    // Calls the existing /api/cron route in-process, so auth and ingest logic stay in one place.
    const request = new Request("https://designpool.io/api/cron", {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    const response: Response = await handler.fetch(request, env, ctx);
    const body = await response.text();
    console.log(`[cron ${controller.cron}] ${response.status} ${body.slice(0, 2000)}`);
    if (!response.ok) throw new Error(`Ingest failed with ${response.status}`);
  },
};

export default worker;

// @ts-expect-error Durable Object classes OpenNext may reference from wrangler.jsonc.
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "../.open-next/worker.js";
